import sys

def solve(n, k, s):
    inf_str = 'RGB' * (n // 3 + 1)
    count = [0] * 3
    for i in range(k):
        count[inf_str[i]] += 1
    ans = float('inf')
    for i in range(3):
        for j in range(i, n, 3):
            if j + k > n:
                break
            cur = 0
            for c in s[j:j+k]:
                cur += 1 if c != inf_str[(j+k-1) % 3] else 0
            ans = min(ans, count[i] + cur)
    return ans

