def polydivisible(x):
    x = str(x)
    for i in range(1, len(x) + 1):
        if int(x[:i]) % i != 0:
            return False
    return True

def unflatten(flat_array):
    result = []
    i = 0
    while i < len(flat_array):
        x = flat_array[i]
        if x < 3:
            result.append(x)
        else:
            subarray = flat_array[i+1:i+x+1]
            result.append(subarray)
            i += x
        i += 1
    return result

