def n00bify(text):
    words = text.split()
    output = []
    for i, w in enumerate(words):
        if w.lower() in ['to', 'too']:
            output.append('2')
        elif w.lower() in ['for', 'fore']:
            output.append('4')
        elif w.lower() == 'be':
            output.append('b')
        elif w.lower() == 'are':
            output.append('r')
        elif w.lower() == 'you':
            output.append('u')
        elif w.lower() == 'please':
            output.append('plz')
        elif w.lower() == 'people':
            output.append('ppl')
        elif w.lower() == 'really':
            output.append('rly')
        elif w.lower() == 'have':
            output.append('haz')
        elif w.lower() == 'know':
            output.append('no')
        elif 'oo' in w:
            output.append(w.replace('oo', '00'))
        elif w.endswith('oo'):
            output.append(w[:-2] + '00')
        else:
            output.append(w)
        if i % 2 == 1:
            output[-1] = output[-1].upper()

    result = ' '.join(output)
    if result.startswith(('h', 'H')):
        result = result.upper()
    if result.startswith(('w', 'W')):
        result = 'LOL ' + result
    if len(result) > 32:
        result = 'OMG ' + result
    result = result.replace('.', '').replace(',', '').replace("'", '')
    if '?' in result:
        q_count = result.count(' ') + 1
        result = result.replace('?', '?' * q_count)
    if '!' in result:
        e_count = result.count(' ') + 1
        result = result.replace('!', '1!'.join(['!'] * e_count))
    return result

