def artificial_rain(garden):
    n = len(garden)
    max_watered = 0

    for i in range(n):
        current_height = garden[i]
        watered = 1
        for j in range(i - 1, -1, -1):
            if garden[j] <= current_height:
                watered += 1
            else:
                break
        for j in range(i + 1, n):
            if garden[j] <= current_height:
                watered += 1
            else:
                break
        max_watered = max(max_watered, watered)

    return max_watered

