def fizz_buzz_cuckoo_clock(time):
    h, m = map(int, time.split(':'))
    h %= 12
    if m == 0:
        return 'Cuckoo ' * h + ('Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo Cuckoo' if h == 0 else '')
    elif m == 30:
        return 'Cuckoo'
    elif m % 3 == 0 and m % 5 == 0:
        return 'Fizz Buzz'
    elif m % 3 == 0:
        return 'Fizz'
    elif m % 5 == 0:
        return 'Buzz'
    else:
        return 'tick'

def merge_first_last(lst):
    if not lst or not lst[0]:
        return []
    return [[lst[i][0], lst[-i-1][-1]] for i in range(len(lst))]

def toggle_bits(n):
    if n == 0 or n == 1:
        return n
    mask = (1 << (n.bit_length() - 1)) - 2
    return n ^ mask

